import unittest


class TestHasCloseElements(unittest.TestCase):
    def test_no_close_elements(self):
        self.assertFalse(has_close_elements([1.0, 2.0, 3.0], 0.5))

    def test_close_elements_exist(self):
        self.assertTrue(has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3))

    def test_empty_list(self):
        self.assertFalse(has_close_elements([], 0.5))

    def test_single_element(self):
        self.assertFalse(has_close_elements([1.0], 0.5))

    def test_two_elements_close(self):
        self.assertTrue(has_close_elements([1.0, 1.1], 0.5))

    def test_two_elements_not_close(self):
        self.assertFalse(has_close_elements([1.0, 3.0], 0.5))

    def test_identical_elements(self):
        self.assertTrue(has_close_elements([1.0, 1.0], 0.1))

    def test_threshold_zero_identical_elements(self):
        self.assertFalse(has_close_elements([1.0, 1.0], 0.0))

    def test_threshold_zero_different_elements(self):
        self.assertFalse(has_close_elements([1.0, 2.0], 0.0))

    def test_negative_numbers_close(self):
        self.assertTrue(has_close_elements([-1.0, -1.1, -3.0], 0.2))

    def test_negative_numbers_not_close(self):
        self.assertFalse(has_close_elements([-1.0, -3.0, -5.0], 0.5))

    def test_mixed_positive_negative_close(self):
        self.assertTrue(has_close_elements([-0.1, 0.1], 0.3))

    def test_mixed_positive_negative_not_close(self):
        self.assertFalse(has_close_elements([-5.0, 5.0], 0.5))

    def test_large_threshold_always_close(self):
        self.assertTrue(has_close_elements([1.0, 100.0], 200.0))

    def test_exact_threshold_boundary_not_close(self):
        self.assertFalse(has_close_elements([1.0, 2.0], 1.0))

    def test_just_under_threshold_is_close(self):
        self.assertTrue(has_close_elements([1.0, 1.99], 1.0))

    def test_many_elements_one_close_pair(self):
        self.assertTrue(has_close_elements([1.0, 5.0, 10.0, 15.0, 15.05], 0.1))

    def test_many_elements_no_close_pair(self):
        self.assertFalse(has_close_elements([1.0, 3.0, 5.0, 7.0, 9.0], 1.0))

    def test_all_identical_elements(self):
        self.assertTrue(has_close_elements([5.0, 5.0, 5.0, 5.0], 0.1))

    def test_floats_with_high_precision(self):
        self.assertTrue(has_close_elements([1.0000001, 1.0000002], 0.001))

    def test_floats_with_high_precision_not_close(self):
        self.assertFalse(has_close_elements([1.0000001, 1.0000002], 0.00000001))

    def test_very_large_numbers_close(self):
        self.assertTrue(has_close_elements([1e10, 1e10 + 0.5], 1.0))

    def test_very_large_numbers_not_close(self):
        self.assertFalse(has_close_elements([1e10, 2e10], 1.0))

    def test_return_type_is_bool(self):
        result = has_close_elements([1.0, 2.0], 0.5)
