import unittest


class TestPrimeFib(unittest.TestCase):
    def test_prime_fib_first(self):
        self.assertEqual(prime_fib(1), 2)

    def test_prime_fib_second(self):
        self.assertEqual(prime_fib(2), 3)

    def test_prime_fib_third(self):
        self.assertEqual(prime_fib(3), 5)

    def test_prime_fib_fourth(self):
        self.assertEqual(prime_fib(4), 13)

    def test_prime_fib_fifth(self):
        self.assertEqual(prime_fib(5), 89)

    def test_prime_fib_sixth(self):
        self.assertEqual(prime_fib(6), 233)

    def test_prime_fib_seventh(self):
        self.assertEqual(prime_fib(7), 1597)

    def test_prime_fib_eighth(self):
        self.assertEqual(prime_fib(8), 28657)

    def test_prime_fib_ninth(self):
        self.assertEqual(prime_fib(9), 514229)

    def test_prime_fib_tenth(self):
        self.assertEqual(prime_fib(10), 433494437)

    def test_prime_fib_returns_int(self):
        result = prime_fib(1)
        self.assertIsInstance(result, int)

    def test_prime_fib_results_are_prime(self):
        import math
        for n in range(1, 8):
            result = prime_fib(n)
            self.assertGreaterEqual(result, 2)
            is_prime = True
            for k in range(2, int(math.sqrt(result)) + 1):
                if result % k == 0:
                    is_prime = False
                    break
            self.assertTrue(is_prime, f"prime_fib({n}) = {result} is not prime")

    def test_prime_fib_results_are_fibonacci(self):
        for n in range(1, 8):
            result = prime_fib(n)
            a, b = 0, 1
            found = False
            while b <= result:
                if b == result:
                    found = True
                    break
                a, b = b, a + b
            self.assertTrue(found, f"prime_fib({n}) = {result} is not a Fibonacci number")

    def test_prime_fib_increasing_sequence(self):
        results = [prime_fib(i) for i in range(1, 8)]
        for i in range(1, len(results)):
            self.assertGreater(results[i], results[i - 1])

    def test_prime_fib_skips_non_prime_fibonacci(self):
        self.assertNotEqual(prime_fib(3), 8)
        self.assertNotEqual(prime_fib(4), 21)

    def test_prime_fib_n_equals_1_is_2(self):
        self.assertEqual(prime_fib(1), 2)


